    const auto hidden{local.DiffSyncSummary(hidden_difference)};
    BOOST_CHECK(!hidden.root_matched);
    BOOST_CHECK_EQUAL(hidden.mismatched_bucket_mask, 0xFFFFU);
    BOOST_TEST_MESSAGE("extra-only relay root bucket mask=" <<
